#include <stdio.h>

int main() {
    int a = 6;
    int b = 7;

    if (a > b) {
        printf("XX\n");
    } else {
        printf("XY\n");
    }

    return 0;
}

    // Pseudo-ops and directives
    ..
main:
    // Program prologue
    ..
    mov     x19, 6              // int a = 6;
    mov     x20, 7              // int b = 7;

    cmp     x19, x20            // Compare a and b: if (a > b)
    b.gt    greaterThan         // Jump to `greaterThan` if the condition code is met

    // else block
    // If the condition code is not met, execution continues with the instruction
    // immediately following the conditional branch.

    ldr     x0, =fmt2           // Load the address of the "XY" string
    bl      printf
    b       end

    // without this branch, execution falls into the if block below

greaterThan:
    ldr     x0, =fmt1           // Load the address of the "XX" string
    bl      printf

end:

    // Code block after the if-else construct
    ..
    // Program epilogue

body.starter:
    .data
    fmt1:   .string "XX\n"
    fmt2:   .string "XY\n"

    .text
    .balign 4
    .global main

main:
    // program prologue
    stp     x29, x30, [sp, -16]!
    mov     x29, sp

    mov     x19, 6              // int a = 6;
    mov     x20, 7              // int b = 7;

    cmp     x19, x20            // Compare a and b: if (a > b)
    b.gt    greaterThan         // Jump to `greaterThan` if the condition code is met

    // else block
    // If the condition code is not met, execution continues with the instruction
    // immediately following the conditional branch.

    ldr     x0, =fmt2           // Load the address of the "XY" string
    bl      printf
    b       end

    // without this branch, execution falls into the if block below

greaterThan:
    ldr     x0, =fmt1           // Load the address of the "XX" string
    bl      printf

end:

    // Code block after the if-else construct

    // program epilogue
    mov     x0, 0
    ldp     x29, x30, [sp], 16
    ret
